"""Plenary evidence, debate, verdict and current Supreme Court integrations."""
import json,sys
from pathlib import Path
CPP='https://www.planalto.gov.br/ccivil_03/decreto-lei/del3689compilado.htm'
T1068='https://portal.stf.jus.br/jurisprudenciarepercussao/verAndamentoProcesso.asp?classeProcesso=RE&incidente=5776893&numeroProcesso=1235340&numeroTema=1068'
T1087='https://portal.stf.jus.br/jurisprudenciaRepercussao/verAndamentoProcesso.asp?classeProcesso=RE&incidente=5745131&numeroProcesso=1225185&numeroTema=1087'
HONOR='https://noticias.stf.jus.br/postsnoticias/tese-da-legitima-defesa-da-honra-e-inconstitucional/'
