rows={}
def add(n,s,p,a,c,v,q,t,d,links=()):
 rows['art-'+str(n)]=dict(simples=s,pontos=p,atencao=[a],exemplo=c+' Variação: '+v,prova=q,termos=[dict(termo=t,significado=d)],remissoes=[CPP,*links])
add(471,'Falta de número para Conselho por exclusões ou recusas leva a adiamento após sorteio de suplentes.', ['Primeiro dia desimpedido.', 'Observar art. 464.', 'Necessidade de sete aptos para Conselho difere do quórum de instalação.'], 'Não julgar com seis nem contar excluído como votante.', 'Recusas deixam só seis aptos: aplicam-se suplência e adiamento.', 'Haver quinze na chamada não garante sete aptos após todas as exclusões.', ['Pode julgar com seis jurados? Não.', 'Quórum inicial garante sempre Conselho apto? Não.'], 'Composição insuficiente','Impossibilidade de formar os sete julgadores.')
add(472,'Formado Conselho, jurados prestam compromisso de imparcialidade e recebem peças de admissibilidade e relatório.', ['Compromisso nominal.', 'Cópias da pronúncia ou decisões posteriores pertinentes e relatório.', 'Pronúncia não é prova de culpa por autoridade.'], 'Receber pronúncia não autoriza condenar porque juiz já decidiu culpa: decisão admite acusação.', 'Jurado recebe documentos para compreender objeto da causa.', 'Acusação não pode convertê-los em argumento de autoridade nos debates.', ['Pronúncia significa condenação anterior? Não.', 'Há compromisso individual nominal? Sim.'], 'Compromisso do jurado','Dever de exame imparcial da causa.')
add(473,'Instrução plenária tem perguntas diretas dos sujeitos previstos e perguntas dos jurados por intermédio do presidente.', ['Testemunhas da acusação: ordem do caput.', 'Testemunhas defensivas: defensor pergunta antes do MP e assistente.', 'Podem pedir acareação, reconhecimento e esclarecimento pericial.', 'Leitura de peças limitada a precatória e provas cautelares, antecipadas ou não repetíveis na hipótese do §3º.'], 'Não dar jurado pergunta direta irrestrita nem converter leitura em reprodução geral do inquérito.', 'Testemunha defensiva recebe primeiro perguntas do defensor no ponto previsto.', 'Jurado pede esclarecimento ao presidente, que intermedeia.', ['Jurado pergunta por intermédio do presidente? Sim.', 'Defesa tem precedência pertinente em sua testemunha? Sim.'], 'Inquirição plenária','Produção de prova com ordem e interlocução definidas.')
add(474,'Acusado presente é interrogado após instrução; partes perguntam diretamente e jurados por intermédio do presidente.', ['Ordem: MP, assistente, querelante e defensor.', 'Garantias de silêncio e entrevista defensiva permanecem.', 'Algemas só se absolutamente necessárias às hipóteses legais, com fundamentação conforme SV11.'], 'Não algemar por rotina, aparência de culpabilidade ou conveniência genérica.', 'Juiz avalia risco concreto e explica necessidade excepcional de algemas.', 'Réu tranquilo sem necessidade demonstrada não deve permanecer algemado só porque responde por crime grave.', ['Algemas são rotina permitida no plenário? Não.', 'Jurado pergunta diretamente ao acusado? Não.'], 'Interrogatório em plenário','Ato defensivo com garantias e segurança excepcional.')
add(475,'Depoimentos e interrogatório devem ter registro fiel; degravação integra autos quando realizada, com leitura jurisprudencial atual.', ['STJ exige necessidade excepcional e prejuízo demonstrado para questão de falta de transcrição.', 'Gravação integral acessível assegura consulta; indisponibilidade exige providência.', 'Não confundir dispensar transcrição automática com negar acesso.'], 'Não declarar nulidade automática só por ausência de texto se há registro acessível; examinar prejuízo e necessidade.', 'Defesa acessa gravação completa para recurso.', 'Arquivo corrompido ou inacessível demanda exame e solução, não resposta de que transcrição nunca importa.', ['Toda ausência de transcrição é nulidade automática? Não.', 'Acesso efetivo ao registro importa? Sim.'], 'Registro e degravação','Documentação audiovisual e transcrição quando necessária.',[RECORD])
add(476,'Debates seguem acusação nos limites da admissibilidade, depois defesa; réplica e tréplica podem ocorrer.', ['Assistente fala após MP.', 'Queixa: querelante antes do MP, salvo retomada de titularidade pelo art. 29.', 'Agravante pode ser sustentada.', 'Pode haver reinquirição de testemunha já ouvida.'], 'Acusação não pode introduzir imputação factual nova livremente só porque tem palavra em plenário.', 'MP sustenta acusação admitida e defesa responde.', 'Fato fora do objeto não pode ser usado como ampliação informal para condenar.', ['Defesa fala após acusação? Sim.', 'Réplica permite tréplica? Sim.'], 'Debates plenários','Argumentação sobre a causa admitida e prova produzida.')
add(477,'Acusação e defesa têm uma hora e meia cada; réplica e tréplica uma hora cada, com ampliação por pluralidade de acusados.', ['Vários acusadores/defensores dividem tempo por acordo ou decisão do presidente.', 'Mais de um acusado: acrescentar uma hora à acusação e defesa; dobrar réplica/tréplica.', 'Não usar tempos individuais da primeira fase como regra do plenário.'], 'Duas defesas não recebem automaticamente uma hora e meia integral cada sob este dispositivo.', 'Dois acusados: acusação e defesa têm duas horas e meia e réplica/tréplica duas horas.', 'Vários advogados combinam distribuição, sem ultrapassar total aplicável.', ['Pluralidade de acusados dobra réplica? Sim.', 'Tempo-base da defesa é uma hora e meia? Sim.'], 'Tempo dos debates','Duração total e repartição conforme composição da causa.')
add(478,'Debates não usam admissibilidade ou algemas como argumento de autoridade, nem silêncio/ausência de interrogatório em prejuízo do acusado.', ['Proibição incide sobre uso de autoridade da decisão, não simples existência do documento.', 'Garantia de silêncio não produz culpa presumida.', 'Nulidade prevista exige exame do ato e regime pertinente.'], 'Dizer que juiz pronunciou, logo réu é culpado viola limite; silêncio não é confissão.', 'Defesa ou acusação discute prova sem afirmar culpa pela pronúncia.', 'Promotor não pode pedir condenação porque réu exerceu silêncio.', ['Silêncio pode ser explorado para prejudicar acusado? Não.', 'Pronúncia prova culpa por autoridade? Não.'], 'Limites argumentativos','Proteção contra autoridade indevida e autoincriminação.')
add(479,'Documento ou objeto sobre fatos exige juntada com três dias úteis de antecedência e ciência da outra parte para leitura/exibição.', ['Inclui jornais, vídeos, gravações, fotos, laudos, quadros, croquis e similares.', 'Prazo em dias úteis.', 'Finalidade: evitar surpresa probatória.'], 'Não exibir vídeo novo no dia do júri sob pretexto de mera ilustração se versa sobre os fatos.', 'Parte junta fotografia com antecedência e comunica adversária.', 'Arquivo factual enviado apenas na manhã da sessão não cumpre requisito automaticamente.', ['São três dias úteis? Sim.', 'Regra alcança vídeo sobre o fato? Sim.'], 'Proibição de surpresa','Antecedência e ciência para material factual exibido.')
add(480,'Partes e jurados podem pedir localização de peça citada por intermédio do presidente; jurados podem pedir esclarecimentos sobre fatos.', ['Após debates, verificar se jurados estão habilitados a julgar.', 'Esclarecer dúvidas fáticas à vista dos autos.', 'Acesso aos autos e instrumentos solicitado ao presidente.'], 'Esclarecer não permite inventar prova ou induzir voto do Conselho.', 'Jurado pede folha da peça citada e consulta pertinente.', 'Presidente não responde dúvida com opinião pessoal de culpa alheia à prova.', ['Pedido passa pelo presidente? Sim.', 'Dúvida permite criar prova? Não.'], 'Esclarecimento aos jurados','Acesso informado à prova com controle do ato.')
add(481,'Fato essencial impossível de verificar imediatamente leva à dissolução do Conselho e diligências necessárias.', ['Se perícia, nomear perito e formular quesitos.', 'Partes podem formular quesitos e indicar assistentes técnicos em cinco dias.'], 'Não confundir dissolução por prova essencial com pausa breve para questão resolvível na hora.', 'Perícia imprescindível não realizável imediatamente leva a diligência e novo procedimento pertinente.', 'Dúvida simples resolvida nos autos não exige dissolução automática.', ['Partes podem indicar assistente em cinco dias? Sim.', 'Toda dúvida dissolve Conselho? Não.'], 'Dissolução por prova essencial','Encerramento da composição para produzir esclarecimento indispensável.')
add(482,'Quesitos tratam dos fatos e da absolvição, em proposições afirmativas, simples e distintas.', ['Considerar admissibilidade, interrogatório e alegações.', 'Cada pergunta precisa de resposta clara e precisa.'], 'Não juntar vários fatos independentes numa pergunta confusa.', 'Presidente separa materialidade e participação em quesitos próprios.', 'Pergunta com duas hipóteses contraditórias não permite voto claro.', ['Proposições devem ser simples e distintas? Sim.', 'Quesito trata só de técnica de dosimetria? Não.'], 'Quesitação','Formulação das perguntas a serem votadas.')
add(483,'Quesitos seguem materialidade, autoria, absolvição e, quando pertinente, diminuição, qualificadoras e aumentos.', ['Quatro votos negativos em materialidade ou autoria encerram com absolvição.', 'Quatro afirmativos em ambos levam ao quesito genérico de absolvição.', 'Desclassificação após segundo ou terceiro conforme caso; tentativa/tipificação de competência do júri após segundo.', 'Crimes/acusados distintos exigem séries distintas.', 'ADPF779 veda legítima defesa da honra.', 'Tema1087 admite recurso da acusação por manifesta contrariedade à prova; clemência registrada e constitucional tem limites específicos.'], 'Quesito genérico não cria absolvição imune a todo recurso nem permite restaurar argumento discriminatório.', 'Após reconhecer fato e autoria, Conselho vota absolvição no quesito próprio.', 'Clemência exige tese em ata e compatibilidade constitucional; não basta rótulo para impedir qualquer revisão.', ['Quatro negativos na autoria podem encerrar votação? Sim.', 'Absolvição genérica é absolutamente irrecorrível? Não.'], 'Quesito absolutório','Pergunta geral inserida após reconhecimento dos requisitos anteriores.',[T1087,HONOR])
add(484,'Presidente lê quesitos, ouve pedidos/reclamações e registra decisão; explica significado ainda em plenário.', ['Ata contém requerimento/reclamação e decisão.', 'Explicação deve ser compreensível e imparcial.'], 'Não omitir objeção da parte nem confundir esclarecimento com indicação de voto.', 'Defesa reclama de quesito composto; presidente decide e registra.', 'Explicar palavra jurídica não autoriza aconselhar condenação.', ['Objeção e decisão vão à ata? Sim.', 'Explicação ocorre ainda em plenário? Sim.'], 'Controle dos quesitos','Ciência e exame das formulações antes da votação.')
add(485,'Votação ocorre em sala especial com os sujeitos enumerados, sem intervenções que perturbem liberdade do Conselho.', ['Sem sala especial, retirar público e manter os autorizados.', 'Retirar quem se porta inconvenientemente nas condições legais.'], 'Sigilo dos votos não significa expulsar defensor ou MP do ato previsto.', 'Defesa acompanha votação sem pressionar jurados.', 'Ausência de sala não leva a votação com plateia influenciando respostas.', ['Defensor está entre participantes previstos? Sim.', 'Público permanece se não há sala especial? Não.'], 'Ambiente de votação','Proteção de voto livre com participantes legais.')
add(486,'Para cada quesito são distribuídas cédulas opacas dobráveis: sete sim e sete não.', ['Cada jurado escolhe resposta.', 'Não confundir quatorze cédulas com quatorze votantes.', 'Sigilo depende da forma e coleta.'], 'Sete sim e sete não representam opções, não número de jurados.', 'Cada um dos sete recebe as opções para voto secreto.', 'Não divulgar escolha pela transparência do papel.', ['Quatorze cédulas significam quatorze jurados? Não.', 'Papel deve ser opaco? Sim.'], 'Cédulas de votação','Opções materiais destinadas ao sigilo da escolha.')
add(487,'Oficial recolhe votos e cédulas não usadas em urnas separadas para garantir sigilo.', ['Separar o que foi votado do que sobrou.', 'Conferência não pode revelar escolha individual.'], 'Não misturar conjuntos ou identificar autor de cada voto.', 'Cédula escolhida vai à urna de votos e sobra à outra.', 'Contagem pública individualizada por jurado destruiria finalidade do sigilo.', ['Urnas devem ser separadas? Sim.', 'Identificar voto de cada jurado é finalidade? Não.'], 'Coleta sigilosa','Recolhimento separado das cédulas.')
add(488,'Conferidos votos e cédulas não utilizadas, registrar votação de cada quesito e resultado no termo.', ['Conferência das sobras também consta.', 'Documentação respeita segredo individual.'], 'Não registrar nome do jurado ligado ao sim/não sob pretexto de detalhamento.', 'Termo informa resultado e conferência regular das cédulas.', 'Ata nominal dos presentes não vira identificação de seus votos.', ['Termo inclui conferência das sobras? Sim.', 'Registro deve revelar escolha individual? Não.'], 'Termo de votação','Documento do resultado e dos controles da votação.')
add(489,'Decisões do júri são tomadas por maioria de votos.', ['Com sete, quatro compõem maioria.', 'Integrar regras de quesitação e segredo.', 'Não exigir unanimidade.'], 'Maioria não elimina controle de contradição entre respostas.', 'Quatro respostas convergentes estabelecem maioria pertinente.', 'Veredito não depende de sete votos iguais.', ['Unanimidade é obrigatória? Não.', 'Quatro de sete formam maioria? Sim.'], 'Maioria','Número de votos suficiente para decisão do Conselho.')
add(490,'Contradição entre respostas é explicada e os quesitos pertinentes voltam à votação; prejudicados são declarados sem voto inútil.', ['Identificar incompatibilidade concreta.', 'Não mudar resposta por discordância do juiz.', 'Quesito genérico absolutório precisa leitura do sistema e Tema1087.'], 'Reconhecer fato/autoria e absolver no quesito genérico não é sempre contradição lógica automática.', 'Duas respostas factualmente incompatíveis exigem explicação e nova votação pertinente.', 'Juiz não impõe condenação apenas porque discordou da absolvição geral.', ['Discordância pessoal autoriza nova votação? Não.', 'Quesitos prejudicados precisam ser todos votados? Não.'], 'Coerência das respostas','Compatibilização sem substituir vontade do Conselho.',[T1087])
add(491,'Termo de votação é assinado por presidente, jurados e partes após encerramento.', ['Assinaturas formalizam documentação.', 'Não revelam voto pessoal.'], 'Assinar termo não significa declarar qual opção cada jurado escolheu.', 'Participantes assinam o registro da votação concluída.', 'Recibo nominal do termo não deve indicar voto individual.', ['Jurados assinam termo? Sim.', 'Assinatura revela voto necessariamente? Não.'], 'Formalização do termo','Registro assinado do procedimento de votação.')
add(492,'Presidente sentencia conforme veredito e integra execução imediata ao Tema1068/STF, sem requisito universal de quinze anos.', ['Condenação: pena-base, agravantes/atenuantes debatidas, causas admitidas e efeitos.', 'Tema1068: execução da condenação pelo corpo de jurados independe do total da pena.', 'Preventiva e execução são fundamentos distintos; recursos e análise de suspensão excepcional preservam regime aplicável.', 'Absolvição: liberdade se não preso por outro motivo; revogar restrições pertinentes; segurança somente se cabível.', 'Desclassificação: presidente sentencia e observa Lei9099 quando pertinente, inclusive conexo não doloso contra vida.', 'Não aplicar recortes de quinze dos parágrafos sem integração ao precedente vinculante.'], 'Não ensinar que pena abaixo de quinze impede execução imediata do júri; não estender regime a toda condenação comum.', 'Condenação de oito anos pelo júri não afasta por valor da pena a regra do Tema1068.', 'Absolvido ainda preso por outra causa não é liberado dessa prisão só pelo veredito deste processo.', ['Tema1068 depende de quinze anos? Não.', 'Preventiva e execução têm fundamento idêntico? Não.'], 'Sentença do júri','Decisão do presidente que concretiza o veredito e efeitos legais.',[T1068])
add(493,'Sentença é lida em plenário antes de encerrar sessão.', ['Ato formal de comunicação do resultado.', 'Não confundir com demais intimações exigidas.'], 'Leitura não dispensa indiscriminadamente todo ato de ciência posterior.', 'Presidente lê sentença ainda na sessão.', 'Notícia informal depois de encerrar não substitui ato previsto.', ['Leitura é antes do encerramento? Sim.', 'Toda intimação posterior é dispensada automaticamente? Não.'], 'Leitura da sentença','Proclamação formal em plenário.')
add(494,'Escrivão lavra ata de cada julgamento, assinada pelo presidente e partes.', ['Distinguir ata geral de termo de votação.', 'Registro da sessão é obrigatório.'], 'Gravação não autoriza simplesmente omitir ata prevista.', 'Secretaria registra sessão e recolhe assinaturas pertinentes.', 'Termo dos quesitos sozinho não descreve todas as ocorrências da ata.', ['Ata é de cada sessão? Sim.', 'Termo de voto substitui toda ata? Não.'], 'Ata da sessão','Documento geral das ocorrências do julgamento.')
add(495,'Ata registra fielmente instalação, presenças, ausências, dispensas, sorteios, prova, debates, incidentes e resultado.', ['Data/hora, presidente, presentes, faltas/escusas/sanções.', 'Requerimentos, suplentes e motivo de adiamento.', 'Abertura, pregão, testemunhas dispensadas/separadas, cédulas e Conselho/recusas.', 'Compromisso/interrogatório, argumentos com fundamentos, incidentes, julgamento e publicidade.', 'Registrar tese defensiva relevante, inclusive clemência no regime do Tema1087.'], 'Resumo não pode apagar objeção ou argumento decisivo; não registrar voto nominal.', 'Ata documenta fundamento de reclamação e tese debatida.', 'Anotar apenas houve debates não substitui registro dos fundamentos exigidos.', ['Fundamentos das alegações devem aparecer? Sim.', 'Ata deve indicar voto de cada jurado? Não.'], 'Fidelidade da ata','Descrição adequada dos atos e argumentos relevantes.',[T1087])
add(496,'Falta de ata sujeita responsável a apuração de sanções administrativas e penais.', ['Consequências demandam regime e pressupostos próprios.', 'Não confundir responsabilidade do registro com culpa do acusado.'], 'Artigo não cria condenação penal automática sem apuração nem autoriza fabricar ata retroativa.', 'Omissão é identificada e apurada pelos meios adequados.', 'Corrigir documentação deve respeitar verdade dos atos e não inventar acontecimentos.', ['Falta permite fabricar registro? Não.', 'Sanção criminal dispensa apuração? Não.'], 'Dever de documentação','Responsabilidade pela ata exigida.')
add(497,'Presidente dirige sessão, resolve direito e incidentes, preserva defesa e ordem, sem substituir decisão factual dos jurados.', ['Força pública e ordem dos trabalhos, dentro dos limites legais.', 'Intervir contra abuso e linguagem excessiva.', 'Indefesa: nomear defensor, podendo dissolver Conselho e redesignar.', 'Retirar acusado que dificulta ato, mantendo defesa.', 'Diligências e pausas necessárias; conservar incomunicabilidade.', 'Extinção da punibilidade ouvidos MP/defesa.', 'Aparte até três minutos acrescido ao tempo de quem estava falando.'], 'Poder de polícia não torna juiz acusador nem legitima punição sumária ou supressão da defesa.', 'Juiz interrompe ataque indevido e garante participação defensiva.', 'Ao conceder aparte, acrescenta tempo ao orador interrompido, não ao interventor.', ['Aparte é acrescido ao tempo de quem estava falando? Sim.', 'Presidente pode ignorar indefesa? Não.'], 'Direção do plenário','Gestão imparcial de ordem, garantias e questões jurídicas.')
assert len(rows)==27
Path(sys.argv[1]).write_text(json.dumps({'course_slug':'codigo-processo-penal','units':rows},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(len(rows),'jury verdict units reviewed')
